 const values=k=>[...new Set(documents.map(d=>d[k]).filter(Boolean))].sort();
 const same=(a,b)=>String(a||"").trim().toLowerCase()===String(b||"").trim().toLowerCase();
 const classMatches=(docClass,chosen)=>chosen==="all"||normalizedClassValues(chosen).some(v=>same(docClass,v));
 const filtered=documents.filter(d=>{const text=`${d.title} ${d.subject||""} ${d.class_level||""} ${d.book_title||""} ${d.description||""}`.toLowerCase();return(filters.category==="all"||d.document_type===filters.category)&&(filters.level==="all"||same(d.education_level,filters.level))&&classMatches(d.class_level,filters.class_level)&&(filters.subject==="all"||same(d.subject,filters.subject))&&(filters.academic_year==="all"||same(d.academic_year,filters.academic_year))&&text.includes(filters.search.toLowerCase())});
