 const coverageSubjects=subjectsForLessonClass(coverageClass);
 const same=(a,b)=>String(a||"").trim().toLowerCase()===String(b||"").trim().toLowerCase();
 const classMatches=(docClass,c)=>normalizedClassValues(c).some(v=>same(docClass,v));
