 async function upload(e){e.preventDefault();if(!file||uploading)return;setUploading(true);setError("");try{const ext=file.name.split(".").pop().toLowerCase();const path=`${form.document_type}/${Date.now()}-${file.name.replace(/[^a-zA-Z0-9._-]/g,"-")}`;const{error:u}=await supabase.storage.from("work-documents").upload(path,file);if(u)throw u;const user=(await supabase.auth.getUser()).data.user;const payload={...form,unit_number:form.unit_number?Number(form.unit_number):null,lesson_plan_count:form.lesson_plan_count?Number(form.lesson_plan_count):null,file_path:path,file_format:ext,status:"published",uploaded_by:user.id};const{error}=await supabase.from("resource_documents").insert(payload);if(error)throw error;setOpen(false);setFile(null);setForm(emptyForm);await load()}catch(e){setError(e.message)}finally{setUploading(false)}}
